package main

import (
	"bytes"
	"fmt"
	"go/format"
	"go/token"
	"strings"

	"github.com/aperturerobotics/protobuf-go-lite/types/descriptorpb"
)

// goNames renames calls the Go library wraps by hand: its Log formats any
// arguments, as fmt.Sprint does.
var goNames = map[string]string{"Log": "logLine"}

// goWriter writes the Go library's generated file.
type goWriter struct {
	s     *schema
	out   bytes.Buffer
	calls []*call
	// unions are the union messages a mod writes and reads.
	unionsIn, unionsOut map[*message]bool
}

// writeGo returns mod/host.gen.go.
func writeGo(s *schema) ([]byte, error) {
	calls, err := s.calls()
	if err != nil {
		return nil, err
	}
	w := &goWriter{s: s, calls: calls}
	var in, out reach
	for _, c := range calls {
		if c.options {
			in.add(c.method.request)
		}
		for _, p := range c.params {
			for _, f := range p.fields() {
				in.addField(f)
			}
		}
		if c.result != nil {
			out.addField(c.result)
		}
	}
	for _, m := range s.mod.methods {
		in.add(m.response)
		out.add(m.request)
	}

	w.out.WriteString(`// Code generated by modlock-sdkgen. DO NOT EDIT.

package mod

import (
	"fmt"

	modlock "github.com/paralin/modlock/proto/modlock"
	"github.com/paralin/modlock/proto/modlock/wasm"
)

// Vector is a position or direction in the world, in game units.
type Vector = modlock.Vec3

// Angles is a rotation in degrees.
type Angles = modlock.EulerAngles

`)
	// Alias the enums and messages a mod uses.
	enums, messages := set(append(in.enums, out.enums...)), set(append(in.messages, out.messages...))
	for _, e := range s.enumOrder {
		if enums[e] {
			w.writeEnum(e)
		}
	}
	w.unionsIn, w.unionsOut = map[*message]bool{}, map[*message]bool{}
	for _, m := range s.messageOrder {
		switch {
		case !messages[m] || m.isEmpty() || mapped(m) != "":
		case m.isUnion():
			w.unionsIn[m], w.unionsOut[m] = set(in.messages)[m], set(out.messages)[m]
		default:
			writeComment(&w.out, "", "//", m.doc)
			fmt.Fprintf(&w.out, "type %s = wasm.%s\n\n", m.name, m.name)
			for _, o := range m.oneofs {
				for _, f := range o.fields {
					fmt.Fprintf(&w.out, "// %s%s sets %s.%s to %s.\n", m.name, camel(f.name), m.name, camel(o.name), camel(f.name))
					fmt.Fprintf(&w.out, "type %s%s = wasm.%s_%s\n\n", m.name, camel(f.name), m.name, camel(f.name))
				}
			}
		}
	}
	for _, m := range s.messageOrder {
		if w.unionsIn[m] || w.unionsOut[m] {
			w.writeUnion(m)
		}
	}

	// Write the classes and calls.
	for _, c := range classes {
		writeComment(&w.out, "", "//", c.doc)
		fmt.Fprintf(&w.out, "type %s struct {\n", c.name)
		writeComment(&w.out, "\t", "//", rename(c.keyDoc, c.key, c.goKey))
		fmt.Fprintf(&w.out, "\t%s %s\n}\n\n", c.goKey, c.goType)
	}
	for _, c := range calls {
		if err := w.writeCall(c); err != nil {
			return nil, err
		}
	}
	w.writeMod()

	formatted, err := format.Source(w.out.Bytes())
	if err != nil {
		return nil, fmt.Errorf("format: %w\n%s", err, w.out.Bytes())
	}
	return formatted, nil
}

// writeEnum aliases an enum and names its values.
func (w *goWriter) writeEnum(e *enum) {
	writeComment(&w.out, "", "//", e.doc)
	fmt.Fprintf(&w.out, "type %s = wasm.%s\n\n", e.name, e.name)
	fmt.Fprintf(&w.out, "// The values of %s.\nconst (\n", e.name)
	for _, v := range e.named() {
		name := e.name + camel(e.valueName(v))
		writeComment(&w.out, "\t", "//", rename(v.doc, v.name, name))
		fmt.Fprintf(&w.out, "\t%s = wasm.%s_%s\n", name, e.name, v.name)
	}
	w.out.WriteString(")\n\n")
}

// writeUnion writes the conversions of a message holding only a oneof,
// which the Go library passes as any of its cases' types.
func (w *goWriter) writeUnion(m *message) {
	o := m.oneofs[0]
	if w.unionsIn[m] {
		fmt.Fprintf(&w.out, "// to%s encodes value as a %s.\n", m.name, m.name)
		fmt.Fprintf(&w.out, "func to%s(value any) (*wasm.%s, error) {\n\tswitch value := value.(type) {\n", m.name, m.name)
		var types []string
		for _, f := range o.fields {
			types = append(types, w.goBase(f))
			fmt.Fprintf(&w.out, "\tcase %s:\n\t\treturn &wasm.%s{%s: &wasm.%s_%s{%s: value}}, nil\n",
				w.goBase(f), m.name, camel(o.name), m.name, camel(f.name), camel(f.name))
		}
		fmt.Fprintf(&w.out, "\t}\n\treturn nil, fmt.Errorf(\"a %s is a %s, not %%T\", value)\n}\n\n", m.name, orList(types))
	}
	if w.unionsOut[m] {
		fmt.Fprintf(&w.out, "// from%s decodes a %s as its case's value, or nil.\n", m.name, m.name)
		fmt.Fprintf(&w.out, "func from%s(message *wasm.%s) any {\n\tswitch value := message.Get%s().(type) {\n", m.name, m.name, camel(o.name))
		for _, f := range o.fields {
			fmt.Fprintf(&w.out, "\tcase *wasm.%s_%s:\n\t\treturn value.%s\n", m.name, camel(f.name), camel(f.name))
		}
		w.out.WriteString("\t}\n\treturn nil\n}\n\n")
	}
}

// orList joins items as "a, b or c".
func orList(items []string) string {
	if len(items) < 2 {
		return strings.Join(items, "")
	}
	return strings.Join(items[:len(items)-1], ", ") + " or " + items[len(items)-1]
}

// writeCall writes one call as a method of its class or a function.
func (w *goWriter) writeCall(c *call) error {
	name := camel(c.name)
	if renamed, ok := goNames[c.method.name]; ok {
		name = renamed
	}
	m := c.method.request

	// Declare the call.
	var params []string
	switch {
	case c.options:
		params = []string{"options *" + m.name}
	default:
		for i, p := range c.params {
			typ := w.paramType(p)
			if i+1 < len(c.params) && w.paramType(c.params[i+1]) == typ {
				typ = ""
			}
			params = append(params, strings.TrimSpace(goParam(p.name)+" "+typ))
		}
	}
	result, failure := w.resultType(c)
	receiver := ""
	if c.class != nil {
		receiver = fmt.Sprintf("(%s %s) ", receiverName(c.class), c.class.name)
	}
	writeComment(&w.out, "", "//", rename(c.method.doc, c.method.name, name))
	fmt.Fprintf(&w.out, "func %s%s(%s) %s {\n", receiver, name, strings.Join(params, ", "), result)
	fail := "return err"
	if failure != "" {
		fail = "return " + failure + ", err"
	}

	// Build the request, as one expression when it needs no statements.
	request := "request"
	switch {
	case m.isEmpty():
		request = "&wasm.Empty{}"
	case c.options && c.receiver == nil:
		request = "options"
	case c.options:
		fmt.Fprintf(&w.out, "\trequest := options.CloneVT()\n\tif request == nil {\n\t\trequest = &%s{}\n\t}\n", m.name)
		fmt.Fprintf(&w.out, "\trequest.%s = %s.%s\n", camel(c.receiver.name), receiverName(c.class), c.class.goKey)
	default:
		var members []string
		if c.receiver != nil {
			members = append(members, fmt.Sprintf("%s: %s.%s", camel(c.receiver.name), receiverName(c.class), c.class.goKey))
		}
		var later []string
		for _, p := range c.params {
			arg := goParam(p.name)
			switch {
			case p.oneof != nil:
				later = append(later, w.oneofCases(m, p.oneof, arg, fail))
			case p.field.message != nil && p.field.message.isUnion():
				later = append(later, fmt.Sprintf("\tencoded, err := to%s(%s)\n\tif err != nil {\n\t\t%s\n\t}\n\trequest.%s = encoded\n",
					p.field.message.name, arg, fail, camel(p.field.name)))
			default:
				members = append(members, fmt.Sprintf("%s: %s", camel(p.field.name), arg))
			}
		}
		literal := fmt.Sprintf("&wasm.%s{%s}", m.name, strings.Join(members, ", "))
		if len(later) == 0 && c.result == nil {
			request = literal
			break
		}
		fmt.Fprintf(&w.out, "\trequest := %s\n", literal)
		w.out.WriteString(strings.Join(later, ""))
	}

	// Exchange it for the response.
	if c.result == nil {
		fmt.Fprintf(&w.out, "\treturn invoke(%q, %s, nil)\n}\n\n", c.method.name, request)
		return nil
	}
	fmt.Fprintf(&w.out, "\tresponse := &wasm.%s{}\n", c.method.response.name)
	fmt.Fprintf(&w.out, "\tif err := invoke(%q, %s, response); err != nil {\n\t\treturn %s, err\n\t}\n", c.method.name, request, failure)
	fmt.Fprintf(&w.out, "\treturn %s, nil\n}\n\n", w.fromField(c.result, "response"))
	return nil
}

// oneofCases returns statements that set the oneof o of request from arg,
// a value of one of its cases' types.
func (w *goWriter) oneofCases(m *message, o *oneof, arg, fail string) string {
	var b strings.Builder
	var types []string
	fmt.Fprintf(&b, "\tswitch %s := %s.(type) {\n", arg, arg)
	for _, f := range o.fields {
		types = append(types, w.goBase(f))
		fmt.Fprintf(&b, "\tcase %s:\n\t\trequest.%s = &wasm.%s_%s{%s: %s}\n", w.goBase(f), camel(o.name), m.name, camel(f.name), camel(f.name), arg)
	}
	err := fmt.Sprintf("fmt.Errorf(\"%s is a %s, not %%T\", %s)", arg, orList(types), arg)
	fmt.Fprintf(&b, "\tdefault:\n\t\t%s\n\t}\n", strings.Replace(fail, "err", err, 1))
	return b.String()
}

// resultType returns a call's result list and the zero value it returns
// with an error, or empty when it returns only an error.
func (w *goWriter) resultType(c *call) (string, string) {
	f := c.result
	if f == nil {
		return "error", ""
	}
	typ := w.goType(f)
	zero := "nil"
	switch {
	case f.repeated || f.optional || f.message != nil:
	case classOf(f) != nil:
		zero = typ + "{}"
	case f.enum != nil:
		zero = "0"
	case f.kind == descriptorpb.FieldDescriptorProto_TYPE_BOOL:
		zero = "false"
	case f.kind == descriptorpb.FieldDescriptorProto_TYPE_STRING:
		zero = `""`
	case f.kind != descriptorpb.FieldDescriptorProto_TYPE_BYTES:
		zero = "0"
	}
	return fmt.Sprintf("(%s, error)", typ), zero
}

// fromField returns the expression that reads the field f of response.
func (w *goWriter) fromField(f *field, response string) string {
	switch {
	case classOf(f) != nil:
		c := classOf(f)
		return fmt.Sprintf("%s{%s: %s.Get%s()}", c.name, c.goKey, response, camel(f.name))
	case f.message != nil && f.message.isUnion():
		return fmt.Sprintf("from%s(%s.Get%s())", f.message.name, response, camel(f.name))
	case f.optional && f.message == nil:
		return response + "." + camel(f.name)
	}
	return fmt.Sprintf("%s.Get%s()", response, camel(f.name))
}

// paramType returns the Go type of one positional parameter.
func (w *goWriter) paramType(p *param) string {
	if p.oneof != nil {
		return "any"
	}
	return w.goType(p.field)
}

// goType returns the Go type of a field as a mod passes or reads it.
func (w *goWriter) goType(f *field) string {
	switch {
	case f.repeated:
		return "[]" + w.goBase(f)
	case f.optional && f.message == nil:
		return "*" + w.goBase(f)
	}
	return w.goBase(f)
}

// goBase returns the Go type of one value of a field.
func (w *goWriter) goBase(f *field) string {
	if c := classOf(f); c != nil {
		return c.name
	}
	switch {
	case f.message != nil && f.message.isUnion():
		return "any"
	case f.message != nil && mapped(f.message) != "":
		return "*" + mapped(f.message)
	case f.message != nil:
		return "*" + f.message.name
	case f.enum != nil:
		return f.enum.name
	}
	return goScalars[f.kind]
}

// goScalars maps each scalar wire type to its Go type.
var goScalars = map[descriptorpb.FieldDescriptorProto_Type]string{
	descriptorpb.FieldDescriptorProto_TYPE_DOUBLE:   "float64",
	descriptorpb.FieldDescriptorProto_TYPE_FLOAT:    "float32",
	descriptorpb.FieldDescriptorProto_TYPE_INT64:    "int64",
	descriptorpb.FieldDescriptorProto_TYPE_UINT64:   "uint64",
	descriptorpb.FieldDescriptorProto_TYPE_INT32:    "int32",
	descriptorpb.FieldDescriptorProto_TYPE_FIXED64:  "uint64",
	descriptorpb.FieldDescriptorProto_TYPE_FIXED32:  "uint32",
	descriptorpb.FieldDescriptorProto_TYPE_BOOL:     "bool",
	descriptorpb.FieldDescriptorProto_TYPE_STRING:   "string",
	descriptorpb.FieldDescriptorProto_TYPE_BYTES:    "[]byte",
	descriptorpb.FieldDescriptorProto_TYPE_UINT32:   "uint32",
	descriptorpb.FieldDescriptorProto_TYPE_SFIXED32: "int32",
	descriptorpb.FieldDescriptorProto_TYPE_SFIXED64: "int64",
	descriptorpb.FieldDescriptorProto_TYPE_SINT32:   "int32",
	descriptorpb.FieldDescriptorProto_TYPE_SINT64:   "int64",
}

// goParam returns a parameter name that is not a Go keyword.
func goParam(name string) string {
	if name == "type" {
		return "kind"
	}
	if token.IsKeyword(name) {
		return name + "Value"
	}
	return name
}

// receiverName returns the receiver variable of a class's methods.
func receiverName(c *class) string {
	return strings.ToLower(c.name[:1])
}

// writeMod writes the interface the mod's handlers implement and the
// dispatch that runs them.
func (w *goWriter) writeMod() {
	w.out.WriteString("// modHandlers handles the events the game delivers to the mod.\ntype modHandlers interface {\n")
	for _, m := range w.s.mod.methods {
		writeComment(&w.out, "\t", "//", m.doc)
		param := ""
		if !m.request.isEmpty() {
			param = "event *" + m.request.name
		}
		result := "error"
		if !m.response.isEmpty() {
			result = fmt.Sprintf("(*%s, error)", m.response.name)
		}
		fmt.Fprintf(&w.out, "\t%s(%s) %s\n", m.name, param, result)
	}
	w.out.WriteString("}\n\n")

	w.out.WriteString("// serveMod runs call on handlers and returns its reply.\n")
	w.out.WriteString("func serveMod(handlers modHandlers, call *wasm.Call) *wasm.Reply {\n\tswitch call.GetMethod() {\n")
	for _, m := range w.s.mod.methods {
		fmt.Fprintf(&w.out, "\tcase %q:\n", m.name)
		event := ""
		if !m.request.isEmpty() {
			fmt.Fprintf(&w.out, "\t\tevent := &%s{}\n\t\tif err := event.UnmarshalVT(call.GetRequest()); err != nil {\n\t\t\treturn &wasm.Reply{Error: err.Error()}\n\t\t}\n", m.request.name)
			event = "event"
		}
		if m.response.isEmpty() {
			fmt.Fprintf(&w.out, "\t\treturn answer(nil, handlers.%s(%s))\n", m.name, event)
			continue
		}
		fmt.Fprintf(&w.out, "\t\treturn answer(handlers.%s(%s))\n", m.name, event)
	}
	w.out.WriteString("\t}\n\treturn &wasm.Reply{Error: \"the mod has no method \" + call.GetMethod()}\n}\n")
}
